import{_ as o,o as a,c as i,j as e,a as n}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Loom","description":"","frontmatter":{"title":"Loom"},"headers":[],"relativePath":"projects/loom/index.md","filePath":"projects/loom/index.md"}'),r={name:"projects/loom/index.md"};function s(l,t,d,c,m,u){return a(),i("div",null,[...t[0]||(t[0]=[e("h1",{id:"loom",tabindex:"-1"},[n("Loom "),e("a",{class:"header-anchor",href:"#loom","aria-label":'Permalink to "Loom"'},"​")],-1),e("p",null,"Loom is a personal work tracker built around a single constraint: capture should require almost no interruption. A single keystroke records what I am working on at that moment — not a task title, not a project assignment, but a brief note of current focus. Over the course of a week, these entries accumulate into a raw log of attention.",-1),e("p",null,"The design assumption is sustained independent work. Team task managers optimise for coordination, assignment, and visibility across people. Loom optimises for something different: a lightweight record of how time and attention actually distribute across weeks of solo analytical work, where the boundary between projects is often fluid and the meaningful unit is what was in front of me when I stopped to note it.",-1),e("p",null,"At the end of each week, a local AI model reads the log and produces a structured summary. The summary is not a productivity report. It describes what was worked on, how effort distributed across themes, and any patterns that emerge from the sequence of entries — shifts in focus, recurring threads, gaps between stated priorities and recorded activity. The model runs locally; the log does not leave the machine.",-1),e("p",null,"The architecture is deliberately minimal. A hotkey listener, a plain-text or lightweight structured store, and a scheduled prompt that passes the week's entries to a local inference endpoint. There is no dashboard, no tagging system, no integration with calendars or email. The friction of categorising work at capture time is treated as a design failure.",-1),e("p",null,"Someone building a similar system would need to decide their own capture granularity, summary schema, and model. The pattern — ambient logging, periodic structured synthesis, local inference — is the transferable part. The specific prompt logic that shapes the weekly summary is not public.",-1),e("hr",null,null,-1),e("p",null,[e("em",null,"Overview available. Methodological detail partial. Full implementation not public.")],-1)])])}const f=o(r,[["render",s]]);export{p as __pageData,f as default};
